D[1619]={"^Your Rejuvenation, Wild Growth and Efflorescence spells have a 5%% chance, and your Healing Touch and Regrowth has a 33%% chance to restore (.-) Energy, (.-) Rage and (.-)%% Mana%.\n\n|cFFAAAAAACapstone Bonus: Healing a target to full health with Healing Touch will restore 30%% of its mana cost%.|r%s*$","Seus feitiços Rejuvenescer, Crescimento Selvagem e Eflorescência têm 5% de chance, e seus feitiços Toque de Cura e Recuperação têm 33% de chance de restaurar {{1}} Energia, {{2}} Fúria e {{3}}% Mana.\n\n|cFFAAAAAABônus de Ápice: Curar um alvo até a vida máxima com Toque de Cura restaurará 30% do custo de mana.|r"}
D[1620]={"^Your Rejuvenation, Wild Growth and Efflorescence spells have a 10%% chance, and your Healing Touch and Regrowth has a 67%% chance to restore (.-) Energy, (.-) Rage and (.-)%% Mana%.\n\n|cFFAAAAAACapstone Bonus: Healing a target to full health with Healing Touch will restore 30%% of its mana cost%.|r%s*$","Seus feitiços Rejuvenescer, Crescimento Selvagem e Eflorescência têm 10% de chance, e seus feitiços Toque de Cura e Recuperação têm 67% de chance de restaurar {{1}} Energia, {{2}} Fúria e {{3}}% Mana.\n\n|cFFAAAAAABônus de Ápice: Curar um alvo até a vida máxima com Toque de Cura restaurará 30% do custo de mana.|r"}
D[1621]={"^Your Rejuvenation, Wild Growth and Efflorescence spells have a 15%% chance, and your Healing Touch and Regrowth has a 100%% chance to restore (.-) Energy, (.-) Rage and (.-)%% Mana%.\n\nCapstone Bonus: Healing a target to full health with Healing Touch will restore 30%% of its mana cost%.%s*$","Seus feitiços Rejuvenescer, Crescimento Selvagem e Eflorescência têm 15% de chance, e seus feitiços Toque de Cura e Recuperação têm 100% de chance de restaurar {{1}} Energia, {{2}} Fúria e {{3}}% Mana.\n\nBônus de Ápice: Curar um alvo até a vida máxima com Toque de Cura restaurará 30% do custo de mana."}
D[2603]={"^|cFF66DDFFLevel 10 Passive|r\nAllows you to auto shoot with a ranged weapon%.\n\nIn addition, reduces the mana cost of all spells and abilities by (.-)%%%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nPermite disparar automaticamente com uma arma de grau.\n\nAlém disso, reduz o custo de mana de todos feitiços e habilidades em {{1}}%."}
D[3666]={"^Increases the bonus healing scaling of |cffffffffLoa's Brew|r and |cFFFFFFFFSpirit in a Bottle|r by (.-)%%%.%s*$","Aumenta a escala de cura adicional de |cffffffffBebida do Loa|r e |cFFFFFFFFEspírito Engarrafado|r em {{1}}%."}
D[3667]={"^|cffffffffLoa's Brew|r affects up to (.-) allies within 8 yds of your target, healing for (.-) every (.-) sec for (.-) sec, stacking (.-) times%.%s*$","|cffffffffBebida do Loa|r afeta até {{1}} aliados em um raio de 8 m do alvo, curando {{2}} a cada {{3}} s durante {{4}} s e acumulando até {{5}} vezes."}
D[3669]={"^Your |cffffffffLethargy Jinx|r now increases your critical strike chance against the target by (.-)%%%.%s*$","Seu |cffffffffMaldição de Letargia|r agora aumenta sua chance de acerto crítico contra o alvo em {{1}}%."}
D[3823]={"^Summon a voodoo ward a short distance infront of you, dealing (.-) Firestorm Damage to up to (.-) nearby targets every (.-) sec for (.-)%. \n\nAt the end of the duration, the ward explodes, dealing (.-) Firestorm Damage to all enemies within (.-) yds%.%s*$","Evoca uma guarda vodu a curta distância à sua frente, causando {{1}} de Dano de Tempestade Fogo até {{2}} alvos próximos a cada {{3}} s durante {{4}}.\n\nAo final da duração, a guarda explode, causando {{5}} de Dano de Tempestade Fogo todos os inimigos dentro de {{6}} m."}
D[3824]={"^Summon a voodoo ward a short distance infront of you, dealing (.-) Firestorm Damage to up to (.-) nearby targets every (.-) sec for (.-)%. \n\nAt the end of the duration, the ward explodes, dealing (.-) Firestorm Damage to all enemies within (.-) yds%.\n\nCan only have 1 |cffffffffWard|r active at a time%.%s*$","Evoca uma guarda vodu a curta distância à sua frente, causando {{1}} de Dano de Tempestade Fogo até {{2}} alvos próximos a cada {{3}} s durante {{4}}.\n\nAo final da duração, a guarda explode, causando {{5}} de Dano de Tempestade Fogo todos os inimigos dentro de {{6}} m\n\nSó pode ter 1 |cffffffffGuarda|r ativa por vez."}
D[3826]={"^Summon a |cffffffffShadow Puppet|r that collects a |cffffffffSpirit|r and rushes towards your target, dealing (.-) Shadow damage, repeating every (.-) sec for (.-)%.%s*$","Evoca uma |cffffffffMarionete de Sombras|r que coleta um |cffffffffEspírito|r e se aproxima ao alvo, causando {{1}} de dano de Sombra, repetindo a cada {{2}} s durante {{3}}."}
D[3827]={"^\nChannel a serpent beam upon an enemy or an ally for up to (.-)%. \n\nDeals (.-) Nature Damage or heals every (.-) sec depending on target%.%s*$","\nCanaliza um feixe de serpente sobre um inimigo ou aliado por até {{1}}.\n\nCausa {{2}} de dano de Natureza ou cura a cada {{3}} s, dependendo do alvo."}
D[3828]={"^|cffffffffInvokes Sseratus|r\nSends a bolt of dark magic at an enemy, inflicting (.-) Shadow Damage, and Stunning them for (.-)%.%s*$","|cffffffffInvoca a Sseratus|r\nLança uma descarga sombria contra um inimigo, causando {{1}} de dano de Sombra e atordoando-o durante {{2}}."}
