D[64900]={"^Brew |cffffffffBloodthistle|r into your |cffffffffCauldron|r%.\n\n|cffffffffCauldron|r: Allies within (.-) yds receive (.-)%% increased healing%.\n\n|cffffffffPotion|r: Causes target ally to leech (.-)%% of all damage they deal for (.-)%. Can only occur once every 0%.5 sec%.%s*$","Mistura |cffffffffCardo-sangue|r em seu |cffffffffCaldeirão|r.\n\n|cffffffffCaldeirão|r: Os aliados dentro de {{1}} m recebem um aumento de {{2}}% na cura recebida.\n\n|cffffffffpoção|r: Faz com que o aliado alvo absorva {{3}}% de todo o dano que causa durante {{4}}. Só pode acontecer uma vez a cada 0,5 s."}
D[64901]={"^Create a copy of yourself that channels voodoo Energy for (.-) on allies within (.-) yds, reducing damage taken by (.-)%%%. \n\nIn addition, you and your summons, while within (.-) yds, are immune to damage, but deal 25%% reduced damage and healing%.%s*$","Cria uma cópia de você mesmo que canaliza Energia vodu durante {{1}} nos aliados dentro de {{2}} m, reduzindo o dano recebido em {{3}}%.\n\nAlém disso, você e suas evocações, enquanto estiverem dentro de {{4}} m, são imunes ao dano, mas causam 25% menos de dano e cura."}
D[64902]={"^Revitalize an ally, healing them for (.-) over (.-), stacking (.-) times%.\n\nAffected allies healing received is increased by (.-)%% for the duration%. Increases the healing allies receive from |cffffffffVoodoo Serpent Beam|r, |cffffffffLoa's Brew|r, and |cffffffffSoothing Juju|r by (.-)%% per stack%.\n\nCan only be used while channeling a Witch Doctor spell upon the target%.%s*$","Revigora um aliado, curando-o em {{1}} ao longo de {{2}}, acumulando até {{3}} vezes.\n\nA cura recebida pelo aliado aumenta em {{4}}% durante o efeito. Cada acúmulo aumenta em {{5}}% a cura recebida de |cffffffffRaio Vodu da Serpente|r, |cffffffffBebida do Loa|r e |cffffffffJuju Calmante|r.\n\nSó pode ser usada enquanto você canaliza um feitiço de Médico Bruxo no alvo."}
D[64903]={"^Revitalize an ally, healing them for (.-) over (.-), stacking (.-) times%.\n\nAffected allies healing received is increased by (.-)%% for the duration%.\n\nCan only be used while channeling a Witch Doctor spell upon the target%.%s*$","Revigora um aliado, curando-o em {{1}} ao longo de {{2}}, acumulando até {{3}} vezes.\n\nA cura recebida pelos aliados afetados aumenta em {{4}}% enquanto durar o efeito.\n\nSó pode ser usada enquanto você canaliza um feitiço de Médico Bruxo no alvo."}
D[64904]={"^Revitalize an ally, healing them for (.-) over (.-), stacking (.-) times%. Increases the healing allies receive from |cffffffffVoodoo Serpent Beam|r, |cffffffffLoa's Brew|r, and |cffffffffSoothing Juju|r by (.-)%% per stack%.\n\nCan only be used while channeling a Witch Doctor spell upon the target%.%s*$","Revigora um aliado, curando-o em {{1}} ao longo de {{2}}, acumulando até {{3}} vezes. Cada acúmulo aumenta em {{4}}% a cura recebida de |cffffffffRaio Vodu da Serpente|r, |cffffffffBebida do Loa|r e |cffffffffJuju Calmante|r.\n\nSó pode ser usada enquanto você canaliza um feitiço de Médico Bruxo no alvo."}
D[64905]={"^Revitalize an ally, healing them for (.-) over (.-), stacking (.-) times%.\n\nCan only be used while channeling a Witch Doctor spell upon the target%.%s*$","Revigora um aliado, curando-o em {{1}} ao longo de {{2}}, acumulando até {{3}} vezes.\n\nSó pode ser usada enquanto você canaliza um feitiço de Médico Bruxo no alvo."}
