T[383]={"^Dealing (.-) Shadow damage every (.-) sec%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} s."}
T[389]={"^Reflecting spells%. Enemies that strike you with a Melee Attack will suffer (.-) Shadow damage%.%s*$","Reflete feitiços. Inimigos que atingirem você com um ataque corpo a corpo sofrem {{1}} de dano de Sombra."}
T[399]={"^Being bombarded by dark Energy%.%s*$","Submetido a bombardeio por Energia sombria."}
T[400]={"^Healing taken reduced by (.-)%%%. Every (.-) sec, you take (.-) Shadow Damage%.%s*$","A cura recebida é reduzido em {{1}}%. a cada {{2}} s, te absorve {{3}} dano de Sombra."}
T[401]={"^Dealing (.-) Shadow damage every (.-) sec%. Increases all Magic damage taken by the Witch Doctor by (.-)%%%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} s. Aumenta em {{3}}% todo o dano mágico recebido do Médico Bruxo."}
T[402]={"^Dealing (.-) Shadow damage every (.-) sec%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} s."}
T[475]={"^Reduces the cast time of |cffffffffLoa's Brew|r by 0%.5 sec%.%s*$","Reduz o tempo de lançamento de |cffffffffBebida do Loa|r em 0,5 s."}
T[545]={"^Increases healing done by (.-)%% and gives all direct healing done an additional (.-)%% chance to cast a free |cffffffffLoa's Brew|r on the target%.%s*$","Aumenta a cura realizada em {{1}}% e concede às curas diretas {{2}}% de chance adicional de lançar gratuitamente |cffffffffBebida do Loa|r no alvo."}
T[596]={"^Nature damage dealt now has a (.-)%% chance to unleash a |cffffffffShadow Puppet|r on an enemy dealing (.-) Shadow damage%.%s*$","O dano de Natureza que se causa agora tem {{1}}% chance de libertar a |cffffffffuna Marionete de Sombras|r inimiga causando {{2}} de dano de Sombra."}
T[827]={"^Increases the damage of |cffffffffAxe Throw|r by (.-)%% for (.-) whenever you gain |cffffffffSavage Rage|r%.%s*$","Aumenta o dano de |cffffffffLançar machados|r em {{1}}% durante {{2}} sempre que obtenha |cffffffffRaiva (Versão Selvagem)|r."}
T[902]={"^Leaping%.%s*$","Salto."}
T[1024]={"^Increases the damage of |cffffffffBad Juju|r by (.-)%% against enemies affected by |cFFFFFFFFHex of Malice|r%.%s*$","Aumenta em {{1}}% o dano de |cffffffffJuju Maligno|r contra inimigos afetados por |cFFFFFFFFMalefício da Malícia|r."}
T[1026]={"^Damage dealt by |cffffffffShadow Puppets|r and |cFFFFFFFFPuppeteer's Threads|r now reduces the cooldown of |cffffffffBatscreech Blast|r by (.-) sec%.%s*$","O dano causado por |cffffffffMarionetes Sombrias|r e |cFFFFFFFFFios do Marionetista|r agora reduz a recarga restante de |cffffffffGrito de Morcego|r em {{1}} s."}
T[1027]={"^Your next Bad Juju triggers a (.-) sec reduced cooldown%.%s*$","Seu próximo Juju Maligno ativa uma redução de recarga de {{1}} s."}
T[1029]={"^Potion Toss and Splash Potion now apply Fish Bones%.%s*$","Poção de Lançamento e Poção de Salpicadura agora aplicam Ossos de Peixe."}
T[1032]={"^Increases the damage reduced by |cffffffffBig Bad Voodoo|r by (.-)%%%.%s*$","Aumenta em {{1}}% a redução de dano de |cffffffffGrande Bruxaria Vodu|r."}
T[1033]={"^Direct critical healing reduces the cooldown of |cffffffffBig Bad Voodoo|r by (.-) sec%.%s*$","A cura crítica direta reduz a recarga de |cffffffffGrande Bruxaria Vodu|r em {{1}} s."}
T[1034]={"^Increases the damage and healing of effects triggered by |cffffffffPotion Toss|r by (.-)%%%.%s*$","Aumenta em {{1}}% o dano e a cura dos efeitos ativados por |cffffffffArremesso de Poção|r."}
T[1037]={"^Increases the effectiveness of all |cffffffffCauldron|r effects and |cffffffffIngredients|r by (.-)%% and you can cast |cffffffffSpirit in a Bottle|r while moving%.%s*$","Aumenta em {{1}}% a eficácia de todos os efeitos de |cffffffffCaldeirão|r e |cffffffffIngredientes|r e permite lançar |cffffffffEspírito Engarrafado|r em movimento."}
T[1038]={"^Gives periodic healing done a chance to reduce the remaining cooldown of |cffffffffPotion Toss|r by (.-) sec%.%s*$","A cura periódica realizada tem chance de reduzir em {{1}} s a recarga restante de |cffffffffArremesso de Poção|r."}
T[1039]={"^Toss a |cffffffffLoa's Brew|r at all allies within (.-)yd that are in your line of sight every (.-) sec for (.-) after using |cffffffffVoodoo Cauldron|r%.%s*$","Após usar |cffffffffBebida do Loa|r, arremessa uma |cffffffffCaldeirão Vodu|r a todos os aliados em sua linha de visão, em um raio de {{1}} m, a cada {{2}} s durante {{3}}."}
T[1044]={"^Damage taken to |cffffffffInvoke Bwonsamdi|r%.%s*$","Dano recebido ao |cffffffffinvocar a Bwonsamdi|r."}
T[1046]={"^Increases the damage and effectiveness of |cffffffffJinxes|r and |cffffffffHexes|r by (.-)%%%.%s*$","Aumenta em {{1}}% o dano e a eficácia de |cffffffffPragas|r e |cffffffffMaldições|r."}
T[1049]={"^|cffffffffArmy of the Loa|r grant all allies a boon based on your current |cffffffffDevotion|r%.%s*$","|cffffffffExército dos Loa|r concede aos aliados um benefício baseado em sua |cffffffffDevoção|r atual."}
T[1050]={"^Increases the healing of |cffffffffDance of the Loa|r by (.-)%%%.%s*$","Aumenta a cura de |cffffffffDança dos Loa|r em {{1}}%."}
