T[1069]={"^Reduces the mana cost of |cffffffffShadow Glaive|r, |cffffffffHexes|r, and |cffffffffJinxes|r by (.-)%%%.%s*$","Reduz em {{1}}% o custo de Mana de |cffffffffGuja Sombria|r, |cffffffffMalefícios|r e |cffffffffPragas|r."}
T[1075]={"^Increases the effectiveness of |cffffffffBwonsamdi|r and |cffffffffBethekk|r spells by (.-)%%%.%s*$","Aumenta a eficácia dos feitiços de |cffffffffBwonsamdi|r e |cffffffffBethekk|r em {{1}}%."}
T[1255]={"^After (.-) you will suffer (.-) Shadow Damage and an additional (.-) Shadow Damage every (.-) sec over (.-)%.%s*$","Depois de {{1}} sofrerá {{2}} dano de Sombra e dano adicional de {{3}} Sombras a cada {{4}} s durante {{5}}."}
