T[11397]={"^Deals 50%% of the damage dealt by Gift of the Loa at the end of the duration%.%s*$","Causa 50% do dano causado por Presente dos loas quando termina o tempo de duração."}
T[11406]={"^Gives damage dealt a (.-)%% chance, and killing an enemy a 100%% chance, to drop their |cffffffffSpirit|r%.%s*$","O dano causado tem {{1}}% de chance, e matar um inimigo tem 100% de chance, de fazer o |cffffffffEspírito|r dele surgir."}
T[12115]={"^Heals an ally with dark magic%.%s*$","Cura um aliado com magia sombria."}
T[12625]={"^Increases damage done by (.-)%%%.\nIncreases damage taken by (.-)%%%.\nSuffering Shadow Damage every second%.%s*$","Aumenta o dano causado em {{1}}%.\nAumenta o dano recebido em {{2}}%.\nSofre dano de Sombra cada segundo."}
T[12627]={"^Increases damage done by (.-)%%%.\nIncreases damage taken by (.-)%%%.\nIncreases healing done by (.-)%%%.%s*$","Aumenta o dano que causas em {{1}}%.\nAumenta o dano que recebe em {{2}}%.\nAumenta a cura que causa em {{3}}%."}
T[12666]={"^Binds the target in a prison of crystal and chains, immobilizing them while their spirit is suppressed by dark magic%.%s*$","Imobiliza o alvo em uma prisão de cristal e correntes enquanto seu Espírito é suprimido por magia sombria."}
T[13329]={"^Calls forth 3 Voodoo Gnomes to destroy your enemies%.%s*$","Evocar 3 gnomos de vodu para destruir a seus inimigos."}
T[14162]={"^|cffffffffLoa's Brew|r affects up to (.-) allies within 8 yds of your target, healing for (.-) every (.-) sec over (.-) sec, stacking (.-) times%.%s*$","|cffffffffBebida do Loa|r afeta até {{1}} aliados em um raio de 8 m de seu alvo, curando em {{2}} a cada {{3}} s durante {{4}} s, acumulando-se {{5}} vezes."}
T[14336]={"^Dealing (.-) Shadow damage every (.-) sec and increases damage taken by Rage of Bethekk and Reclamation by (.-)%%%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} s e aumenta o dano recebido pela Fúria de Bethekk e Recuperação em {{3}}%."}
T[14337]={"^Dealing (.-) Shadow damage every (.-) sec%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} s."}
T[14338]={"^Taking an additional attack from a nearby Serpent Ward every (.-) sec%.%s*$","Recebe um ataque adicional de uma Sentinela Serpente próxima a cada {{1}} s."}
T[14342]={"^Deals 72 Frost damage to attackers%.%s*$","Causa 72 dano de Gelo aos atacantes."}
T[14343]={"^Dealing (.-) Shadow damage every (.-) sec%. Increases all Magic damage taken by the Witch Doctor by (.-)%%%.%s*$","Causa {{1}} de dano de Sombra a cada {{2}} s. Aumenta em {{3}}% todo o dano mágico recebido do Médico Bruxo."}
T[14367]={"^Reduces the cast time of |cffffffffLoa's Brew|r by 0%.5 sec%.%s*$","Reduz o tempo de lançamento de |cffffffffBebida do Loa|r em 0,5 s."}
T[14401]={"^(.-)%% of total Health regeneration may continue during combat%.%s*$","Até {{1}}% dá regeneração total de vida pode continuar durante o combate."}
T[14456]={"^Leeches Mana%.%s*$","Drena Mana."}
T[14639]={"^Reduces the remaining cooldown of Potion Toss by (.-) sec%.%s*$","Reduz a recarga restante de Arremesso de Poção em {{1}} s."}
T[14642]={"^|cffffffffHex of Death|r increases the damage and healing of your next |cffffffffBwonsamdi|r ability by (.-)%%%.%s*$","|cffffffffMalefício da Morte|r aumenta em {{1}}% o dano e a cura de sua próxima habilidade de |cffffffffBwonsamdi|r."}
