T[14645]={"^|cffffffffArmy of the Loa|r grant all allies a boon based on your current |cffffffffDevotion|r%.%s*$","|cffffffffExército dos Loa|r concede aos aliados um benefício baseado em sua |cffffffffDevoção|r atual."}
T[14646]={"^When |cffffffffBad Juju|r is used on enemies affected by |cffffffffPuppeteer's Threads|r, it strikes an additional time every (.-) sec for 30%% of the damage dealt over (.-) as Nature damage%.%s*$","Quando usada |cffffffffJuju Maligno|r sobre inimigos afetados por |cffffffffFios do Marionetista|r, golpeia uma vez mais a cada {{1}} s causando 30% do dano causado como dano de Natureza durante {{2}}."}
T[14647]={"^Damage dealt by |cffffffffShadow Puppets|r increases the damage the enemy takes from |cffffffffMalefic Wrath|r and |cffffffffHexfire|r by (.-)%%, stacking (.-) times, for (.-)%.%s*$","O dano causado por |cffffffffMarionetes Sombrias|r aumenta o dano que recebe o inimigo do |cffffffffIra Maléfica|r e |cffffffffFogo Bruxuleante|r em {{1}}%, acumulando-se {{2}} vezes, durante {{3}}."}
T[14695]={"^Dealing 705910s1%% of Bad Juju's damage every (.-) sec%.%s*$","Causa 705910s1% do dano de Juju Maligno a cada {{1}} s."}
T[14704]={"^Your next Spirit Glaive is guaranteed to critically strike and reduces the cooldown of Shadowstalker by 15 sec%.%s*$","Seu próximo Guja Espírito está garantido a ser um acerto crítico e reduz a recarga de Atrapasombras em 15 s."}
T[14705]={"^Your next Malefic Arrow has no cooldown, is guaranteed to critically strike, and reduces the cooldown of Shadowstalker by 15 sec%.%s*$","Sua próxima Flecha Maligna não tem recarga, está garantida ser um acerto crítico e reduz a recarga de Atrapasombras em 15 s."}
T[14717]={"^Increases damage dealt against enemies below 35%% health by (.-)%%%.%s*$","Aumenta o dano causado aos inimigos abaixo de 35% de vida em {{1}}%."}
T[14718]={"^Malefic Wrath now strikes 2 additional nearby enemies and is guaranteed to apply Puppeteer's Threads%.%s*$","Agora Raiva Maligna golpeia 2 inimigos próximos adicionais e garante que se aplique os Fios do Marionetista."}
T[14764]={"^After (.-) you will suffer (.-) Shadow Damage and an additional (.-) Shadow Damage every (.-) sec over (.-)%.%s*$","Depois de {{1}} sofrerá {{2}} dano de Sombra e dano adicional de {{3}} Sombras a cada {{4}} s durante {{5}}."}
T[14814]={"^Being Revitalized%. Healing taken from the Witch Doctor's Voodoo Serpent Beam, Loa's Brew, and Soothing Juju increased by (.-)%%%. Stacks (.-) times%.%s*$","Sendo Revitalizado. A cura recebida do faça de serpente vodu, a Poção dos deuses loa e o Suco reconfortante aumenta em {{1}}%. Acumula {{2}} vezes."}
T[14815]={"^Being Revitalized%.%s*$","Sendo Revitalizado."}
T[14819]={"^Drink a potent voodoo draught that slows your body to a deathlike stillness for up to (.-), causing you to feign death which may trick enemies into ignoring you%.%s*$","Bebe uma poderosa poção vodu que deixa seu corpo imóvel como um cadáver por até {{1}}, fazendo você fingir de morto e podendo enganar os inimigos para que ignorem você."}
T[14838]={"^Movement speed reduced by (.-)%%%. Periodic healing received reduced by (.-)%%%.%s*$","Velocidade de movimento reduzida em {{1}}%. Cura periódica recebida reduzida em {{2}}%."}
